from fractions import Fraction
import math, itertools

def frac_tex(f):
    f = Fraction(f)
    if f.denominator == 1:
        return str(f.numerator)
    sign = "-" if f < 0 else ""
    return sign + "\\frac{%d}{%d}" % (abs(f.numerator), f.denominator)

def shoelace_area(pts):
    s = 0
    n = len(pts)
    for i in range(n):
        x1, y1 = pts[i]
        x2, y2 = pts[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return Fraction(abs(s), 2)

